import{_ as t,o as s,c as i,a4 as n}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"Pack Secteur public FR","description":"Pack Secteur public FR : ses extensions.","frontmatter":{"title":"Pack Secteur public FR","description":"Pack Secteur public FR : ses extensions."},"headers":[],"relativePath":"extensions/packs/secteur-public-fr.md","filePath":"extensions/packs/secteur-public-fr.md"}'),a={name:"extensions/packs/secteur-public-fr.md"};function r(d,e,u,o,c,l){return s(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="pack-secteur-public-fr" tabindex="-1">Pack Secteur public FR <a class="header-anchor" href="#pack-secteur-public-fr" aria-label="Permalink to &quot;Pack Secteur public FR&quot;">​</a></h1><p>Les plugins d&#39;une collectivité française, transcrits du corpus Les MogWais : démarches en ligne, annuaires, actualités, agenda, marchés publics et composition de page.</p><p>Un pack est une façon de <strong>lire</strong> le catalogue, pas une unité d&#39;installation : les extensions s&#39;installent une par une, et une extension peut figurer dans plusieurs packs (<a href="/teuthis-cms-distribution/developpeurs/adr/0028-packs-verticaux-du-catalogue-livre">ADR-0028</a>). Ce pack réunit 25 extensions.</p><h2 id="extensions" tabindex="-1">Extensions du pack <a class="header-anchor" href="#extensions" aria-label="Permalink to &quot;Extensions du pack {#extensions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Extension</th><th>Ce qu&#39;elle apporte</th><th>En une phrase (notice d&#39;utilisation)</th><th>Autres packs</th></tr></thead><tbody><tr><td><a href="/teuthis-cms-distribution/extensions/accordeon">Accordéon</a></td><td>Blocs : Accordéon (cliquer-dérouler), Élément d&#39;accordéon</td><td>Le bloc « cliquer-dérouler », qui peut contenir d&#39;autres blocs.</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/actualites">Actualités</a></td><td>Types de contenu : Actualité</td><td>Le fil d&#39;actualités du site, avec un formulaire public « Proposer une actualité » et une localisation facultative, choisie dans l&#39;annuaire des lieux ou saisie librement.</td><td><a href="/teuthis-cms-distribution/extensions/packs/boutique">Boutique</a>, <a href="/teuthis-cms-distribution/extensions/packs/redaction">Rédaction</a></td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/agenda">Agenda</a></td><td>Types de contenu : Événement</td><td>Le calendrier d&#39;événements du site, avec formulaire public de proposition, ajout au calendrier personnel du visiteur, et dépublication automatique une fois l&#39;événement passé.</td><td><a href="/teuthis-cms-distribution/extensions/packs/agence">Agence</a></td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/albums">Albums photos/vidéos</a></td><td>Types de contenu : Album photos/vidéos</td><td>Des albums mêlant photos et vidéos, présentés en fiches, avec une page liste filtrable.</td><td><a href="/teuthis-cms-distribution/extensions/packs/boutique">Boutique</a>, <a href="/teuthis-cms-distribution/extensions/packs/redaction">Rédaction</a>, <a href="/teuthis-cms-distribution/extensions/packs/agence">Agence</a></td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/annuaire-elus">Annuaire des élu-e-s</a></td><td>Types de contenu : Élu-e</td><td>La fiche d&#39;un-e élu-e (mandats et fonctions, permanences, portrait, réseaux sociaux). Elle porte aussi ses délégations (« Finances », « Jeunesse et sports »).</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/annuaire-lieux">Annuaire des lieux</a></td><td>Types de contenu : Lieu</td><td>Un répertoire interne de lieux (mairie annexe, gymnase, médiathèque...) pour rattacher précisément une actualité ou un événement à une adresse existante, plutôt que de la ressaisir à chaque fois.</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/annuaire-personnes">Annuaire de personnes</a></td><td>Types de contenu : Personne</td><td>Un annuaire de fiches personnelles (élus, agents, contacts d&#39;association) avec attestation obligatoire d&#39;autorisation de publication : une fiche non attestée reste modifiable par son auteur mais …</td><td><a href="/teuthis-cms-distribution/extensions/packs/boutique">Boutique</a>, <a href="/teuthis-cms-distribution/extensions/packs/redaction">Rédaction</a>, <a href="/teuthis-cms-distribution/extensions/packs/agence">Agence</a></td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/annuaires-structure">Annuaires de structure</a></td><td>Types de contenu : Association, Commerce, Équipement, Service</td><td>Quatre annuaires indépendants — associations, commerces, équipements, services — chacun avec sa propre page et ses propres thématiques, bâtis sur une même fiche (coordonnées, horaires, réseaux …</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/calendrier-travaux">Calendrier des travaux</a></td><td>Types de contenu : Chantier</td><td>Les chantiers en cours et à venir, datés, localisés, avec le contact du service qui les suit.</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/cartography">Cartographie</a></td><td>Blocs : Localiser</td><td>Le bloc « Localiser » pour afficher des contenus sur une carte (réglages de fond de carte, regroupement des points, navigation au clavier).</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/comments">Commentaires</a></td><td>Réglages : Autoriser les commentaires</td><td>Une extension volontairement minimale, qui ajoute la case « Autoriser les commentaires » au panneau de configuration d&#39;un contenu — elle sert de démonstration du mécanisme d&#39;extension et ne fournit …</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/enquetes">Enquêtes et études d&#39;opinion</a></td><td>Types de contenu : Enquête, Réponse à une enquête</td><td>Des questionnaires à plusieurs questions (échelles d&#39;accord, choix unique ou multiple, texte libre). Les réponses ne sont consultables qu&#39;en back-office.</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/faq">FAQ</a></td><td>Types de contenu : Question de FAQ</td><td>Une foire aux questions, avec un formulaire public de dépôt d&#39;une question — la question devient une fiche que l&#39;équipe complète d&#39;une réponse avant de la publier.</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/flash-info">Flash info</a></td><td>Types de contenu : Flash info</td><td>Un bandeau ou une fenêtre d&#39;alerte affichée en tête de toutes les pages publiques, avec sa propre programmation de début et de fin d&#39;affichage.</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/glossaire">Glossaire</a></td><td>Types de contenu : Terme de glossaire</td><td>Un glossaire de termes administratifs, présenté par ordre alphabétique ; tout terme qui y figure devient automatiquement un lien vers sa définition partout ailleurs où il apparaît sur le site.</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/marches-publics">Marchés publics</a></td><td>Types de contenu : Marché public</td><td>Les avis de marché public en cours, avec date limite de réponse, statut d&#39;attribution et documents à télécharger.</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/navigation">Navigation</a></td><td>Blocs : Menu des sous-pages, Page sommaire</td><td>Les blocs « Menu des sous-pages » et « Page sommaire », qui construisent leur liste depuis l&#39;arbre des pages et respectent les restrictions d&#39;accès.</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/offre-de-soins">Offre de soins</a></td><td>Types de contenu : Bâtiment, Unité d&#39;hospitalisation, Pôle, Équipe médicale, Service, Médecin, Consultation</td><td>Sept fiches liées entre elles pour un établissement de santé — bâtiments, unités d&#39;hospitalisation, pôles, services, équipes médicales, médecins, consultations.</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/offres-emploi">Offres d&#39;emploi</a></td><td>Types de contenu : Offre d&#39;emploi, Candidature à une offre d&#39;emploi, Candidature spontanée</td><td>Les offres d&#39;emploi de la collectivité, avec deux formulaires publics de candidature — l&#39;un pour postuler à une offre précise, l&#39;autre en candidature spontanée — chacun notifiant automatiquement la …</td><td><a href="/teuthis-cms-distribution/extensions/packs/agence">Agence</a></td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/paroles-acteurs">Paroles d&#39;acteurs</a></td><td>Types de contenu : Parole d&#39;acteur</td><td>Un recueil de témoignages (portraits, interviews) présentés en fiches, avec une page liste filtrable.</td><td><a href="/teuthis-cms-distribution/extensions/packs/boutique">Boutique</a>, <a href="/teuthis-cms-distribution/extensions/packs/agence">Agence</a></td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/publications">Publications</a></td><td>Types de contenu : Publication</td><td>Une bibliothèque de documents à télécharger (rapports, bulletins, délibérations), avec fiche par document, liste filtrable et flux RSS.</td><td><a href="/teuthis-cms-distribution/extensions/packs/redaction">Rédaction</a></td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/rdv-reservations">RDV &amp; réservations</a></td><td>Types de contenu : Service réservable, Demande de réservation</td><td>Des services réservables (permanences, équipements, salles) et le formulaire public de demande.</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/sondages">Sondages</a></td><td>Types de contenu : Sondage</td><td>Une question, plusieurs réponses, un vote public et ses résultats. Le blocage d&#39;un second vote depuis le même navigateur est optionnel et ne stocke rien côté serveur.</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/sve">Saisine par voie électronique</a></td><td>Types de contenu : Demande de saisine</td><td>Le circuit complet d&#39;une démarche en ligne côté back-office (tableau de bord des dossiers, export, échange de messages avec l&#39;usager).</td><td>—</td></tr><tr><td><a href="/teuthis-cms-distribution/extensions/widgets-accueil">Widgets de page d&#39;accueil</a></td><td>Blocs : Accès rapides, Avancer ensemble, Actualités, Actualités — En bref, Agenda, Albums, Publications, Paroles d&#39;acteur, Annuaires &amp; carte — Proche de vous, Découvrir, Mise en avant — Images ou vidéo, Mots-clés</td><td>Douze blocs prêts à poser sur une page d&#39;accueil — accès rapides, mise en avant, découvrir, actualités et brèves, agenda, albums, publications, mots-clés, annuaires et carte.</td><td>—</td></tr></tbody></table><p>La présentation de chaque extension est dans la <a href="/teuthis-cms-distribution/documentation/notice/3-extensions-plugins">notice d&#39;utilisation</a> ; les pages ci-dessus ajoutent ce que les manifestes déclarent.</p>',6)])])}const h=t(a,[["render",r]]);export{m as __pageData,h as default};
